def normalize(value):
    if isinstance(value, bytes):
        return ("bytes", value)
    return ("json", json.dumps(value, ensure_ascii=False))


def outcome(mod, fn):
    try:
        return ("ok", normalize(fn(mod)))
    except Exception as exc:  # noqa: BLE001 - classification is the point
        return ("raise", type(exc).__name__, str(exc))


def main():
    failures = 0
    for name, fn in CASES:
        before = outcome(baseline, fn)
        after = outcome(current, fn)
        if before != after:
            failures += 1
            print(f"MISMATCH {name}\n  baseline: {before!r}\n"
                  f"  current:  {after!r}")
    # Input immutability on the refactored module.
    for name, fn in IMMUTABLE_CALLS:
        snapshot = copy.deepcopy(fx.__dict__)
        fn(current)
        for key, before_value in snapshot.items():
            if not _equal(fx.__dict__[key], before_value):
                failures += 1
                print(f"MUTATED {name}: fixture attribute {key!r} changed")
    # Deep independence: repeated calls are equal but not shared.
    for name, fn in IMMUTABLE_CALLS:
        try:
            first = fn(current)
            second = fn(current)
        except Exception:  # noqa: BLE001
            continue
        if normalize(first) != normalize(second):
            failures += 1
            print(f"NONDETERMINISTIC {name}")
        if isinstance(first, dict):
            first_json = normalize(first)
            _corrupt(first)
            if normalize(second) != normalize(fn(current)):
                failures += 1
                print(f"SHARED STATE {name}: results are not independent")
            del first_json
    print(f"{len(CASES)} cases, {failures} mismatch(es)")
    return 1 if failures else 0


def _equal(a, b):
    try:
        return a == b
    except Exception:  # noqa: BLE001
        return False


def _corrupt(value):
    if isinstance(value, dict):
        for key in value:
            value[key] = None
            return
    if isinstance(value, list) and value:
        value[0] = None


if __name__ == "__main__":
    sys.exit(main())

